page.css:
:root{
  --slate:#384b5f;      /* primary brand */
  --navy:#2c3e50;       /* dark sections */
  --blue:#1992ca;       /* action / accents */
  --blue-dark:#0e6c99;  /* derived from --blue for AA white-on-blue */
  --red:#c41f27;        /* accent / urgency */
  --red-dark:#a5171e;
  --ink:#333333;        /* body text */
  --muted:#5c6b7a;
  --grey:#e8e8e8;
  --off:#f4f7f9;        /* alt section surface */
  --line:#dde5ec;
  --white:#ffffff;
  --head:Arial,"Helvetica Neue",Helvetica,sans-serif;
  --body:"Cabin",Arial,sans-serif;
  --wrap:1180px;
  --radius:12px;
  --shadow:0 8px 30px rgba(44,62,80,.12);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--body);color:var(--ink);line-height:1.65;background:var(--white);font-size:17px}
h1,h2,h3,h4{font-family:var(--head);font-weight:800;color:var(--slate);line-height:1.15;margin:0 0 .5em}
h1{font-size:clamp(2rem,4.6vw,3.15rem);letter-spacing:-.5px}
h2{font-size:clamp(1.55rem,3.2vw,2.3rem);letter-spacing:-.3px}
h3{font-size:1.2rem}
p{margin:0 0 1.1em}
a{color:var(--blue-dark);text-decoration:none}
a:hover{text-decoration:underline}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.skip{position:absolute;left:-999px;top:0;background:var(--navy);color:#fff;padding:10px 16px;z-index:200}
.skip:focus{left:8px;top:8px}
img{max-width:100%;height:auto;display:block}
:focus-visible{outline:3px solid var(--blue);outline-offset:2px}

/* buttons */
.btn{display:inline-flex;align-items:center;gap:.55em;font-family:var(--head);font-weight:800;
  padding:.85em 1.5em;border-radius:8px;cursor:pointer;border:2px solid transparent;font-size:1rem;transition:.15s;text-align:center;justify-content:center}
.btn:hover{text-decoration:none;transform:translateY(-1px)}
.btn-red{background:var(--red);color:#fff}
.btn-red:hover{background:var(--red-dark);color:#fff}
.btn-blue{background:var(--blue-dark);color:#fff}
.btn-blue:hover{background:#0b587e;color:#fff}
.btn-ghost{background:transparent;color:#fff;border-color:rgba(255,255,255,.7)}
.btn-ghost:hover{background:rgba(255,255,255,.12);color:#fff}
.btn-lg{padding:1em 1.8em;font-size:1.08rem}

/* top bar */
.topbar{background:var(--red);color:#fff;font-size:.9rem}
.topbar .wrap{display:flex;justify-content:space-between;align-items:center;gap:14px;padding-top:8px;padding-bottom:8px;flex-wrap:wrap}
.topbar strong{font-family:var(--head)}
.topbar .tb-r{display:flex;align-items:center;gap:8px;opacity:.95}

/* header */
header.site{position:sticky;top:0;z-index:100;background:#fff;box-shadow:0 1px 0 rgba(0,0,0,.08)}
.hrow{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:10px 0}
.logo img{height:58px;width:auto}
nav.main{display:flex;align-items:center;gap:26px}
nav.main ul{display:flex;align-items:center;gap:26px;list-style:none;margin:0;padding:0}
nav.main a.nav-link{font-family:var(--head);font-weight:700;color:var(--slate);font-size:1rem;padding:6px 0}
nav.main a.nav-link:hover{color:var(--red);text-decoration:none}
.has-drop{position:relative}
.has-drop>button{font-family:var(--head);font-weight:700;color:var(--slate);background:none;border:0;font-size:1rem;cursor:pointer;display:flex;align-items:center;gap:6px;padding:6px 0}
.has-drop>button:hover{color:var(--red)}
.drop{position:absolute;top:100%;left:50%;transform:translateX(-50%);background:#fff;box-shadow:var(--shadow);border-radius:10px;
  padding:10px;min-width:250px;display:none;flex-direction:column;border:1px solid var(--line);z-index:50}
.has-drop:hover .drop,.has-drop:focus-within .drop{display:flex}
.drop a{padding:9px 12px;border-radius:7px;color:var(--slate);font-weight:600;font-size:.96rem}
.drop a:hover{background:var(--off);color:var(--blue-dark);text-decoration:none}
.hactions{display:flex;align-items:center;gap:14px}
.search-ic{color:var(--slate);font-size:1.05rem;padding:6px}
.burger{display:none;background:none;border:0;font-size:1.5rem;color:var(--slate);cursor:pointer;padding:6px}

/* breadcrumb */
.crumb{background:var(--off);border-bottom:1px solid var(--line);font-size:.86rem}
.crumb .wrap{padding:11px 22px}
.crumb ol{list-style:none;display:flex;flex-wrap:wrap;gap:8px;margin:0;padding:0;color:var(--muted)}
.crumb a{color:var(--muted)}
.crumb li[aria-current]{color:var(--slate);font-weight:600}
.crumb i{color:var(--muted);font-size:.7rem;margin-left:8px}

/* hero */
.hero{position:relative;background:linear-gradient(135deg,var(--navy) 0%,var(--slate) 60%,#31536e 100%);color:#fff;overflow:hidden}
.hero .wrap{position:relative;z-index:2;padding:64px 22px 88px}
.hero .eyebrow{display:inline-flex;align-items:center;gap:9px;background:rgba(25,146,202,.22);border:1px solid rgba(255,255,255,.28);
  color:#fff;font-family:var(--head);font-weight:700;letter-spacing:.4px;text-transform:uppercase;font-size:.76rem;padding:7px 14px;border-radius:999px;margin-bottom:20px}
.hero h1{color:#fff;max-width:16ch}
.hero .lead{font-size:1.2rem;max-width:52ch;color:#eaf1f6;margin-bottom:26px}
.hero-cta{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:30px}
.chips{display:flex;flex-wrap:wrap;gap:12px 22px}
.chips .chip{display:flex;align-items:center;gap:9px;font-weight:600;font-size:.98rem;color:#eef4f8}
.chips .chip i{color:#6fd0ff;font-size:1.05rem}
.skyline{position:absolute;left:0;right:0;bottom:0;width:100%;height:120px;z-index:1;opacity:.16}

/* trust strip */
.trust{background:var(--slate);color:#fff}
.trust .wrap{display:flex;flex-wrap:wrap;justify-content:space-between;gap:14px 20px;padding:16px 22px}
.trust .t{display:flex;align-items:center;gap:10px;font-family:var(--head);font-weight:700;font-size:.95rem}
.trust .t i{color:#6fd0ff;font-size:1.15rem}

/* sections */
section{padding:62px 0}
.section-head{max-width:66ch;margin-bottom:8px}
.section-head p.k{font-family:var(--head);font-weight:800;text-transform:uppercase;letter-spacing:.6px;color:var(--blue-dark);font-size:.8rem;margin-bottom:8px}
.lead-2{font-size:1.12rem;color:var(--muted)}
.alt{background:var(--off)}
.two{display:grid;grid-template-columns:1.15fr .85fr;gap:40px;align-items:center}

/* image placeholder */
.img-ph{border:2px dashed #b9c6d2;background:repeating-linear-gradient(45deg,#eef3f7,#eef3f7 12px,#e7eef4 12px,#e7eef4 24px);
  border-radius:var(--radius);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;
  color:var(--muted);padding:26px;min-height:230px;font-size:.86rem}
.img-ph i{font-size:1.9rem;color:#9db0c1;margin-bottom:10px}
.img-ph b{font-family:var(--head);color:var(--slate);letter-spacing:.4px;font-size:.8rem;text-transform:uppercase}
.img-ph span{display:block;margin-top:4px}
.img-band{min-height:300px}

/* service cards */
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.card{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:26px 24px;transition:.18s;position:relative;overflow:hidden}
.card:before{content:"";position:absolute;left:0;top:0;height:4px;width:100%;background:var(--blue)}
.card:hover{box-shadow:var(--shadow);transform:translateY(-3px);border-color:#cfe0ec}
.card .ic{width:52px;height:52px;border-radius:10px;background:var(--off);display:flex;align-items:center;justify-content:center;margin-bottom:16px}
.card .ic i{font-size:1.4rem;color:var(--blue-dark)}
.card h3{margin-bottom:.4em}
.card p{font-size:.97rem;color:var(--muted);margin-bottom:1em}
.card a.more{font-family:var(--head);font-weight:700;color:var(--blue-dark);font-size:.95rem;display:inline-flex;align-items:center;gap:7px}
.card a.more:hover{gap:11px;text-decoration:none}

/* why choose */
.feat{display:grid;grid-template-columns:repeat(2,1fr);gap:20px 34px}
.feat .f{display:flex;gap:16px}
.feat .f i{color:var(--red);font-size:1.35rem;margin-top:3px;flex:none;width:26px;text-align:center}
.feat .f h3{margin-bottom:.25em;font-size:1.08rem}
.feat .f p{margin:0;color:var(--muted);font-size:.97rem}

/* process */
.process{background:var(--navy);color:#fff}
.process h2{color:#fff}
.process .lead-2{color:#c6d3df}
.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:22px;margin-top:34px;counter-reset:s}
.step{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);border-radius:var(--radius);padding:26px 22px;position:relative}
.step .n{width:44px;height:44px;border-radius:50%;background:var(--red);color:#fff;font-family:var(--head);font-weight:800;
  display:flex;align-items:center;justify-content:center;font-size:1.15rem;margin-bottom:14px}
.step h3{color:#fff;font-size:1.08rem}
.step p{color:#c6d3df;font-size:.95rem;margin:0}

/* booking */
.book .wrap{display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:start}
.book ul.reass{list-style:none;padding:0;margin:18px 0 0}
.book ul.reass li{display:flex;gap:12px;align-items:flex-start;margin-bottom:14px;font-weight:500}
.book ul.reass i{color:var(--blue-dark);margin-top:4px}
form.enq{background:#fff;border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow);padding:28px}
form.enq h3{font-size:1.3rem;margin-bottom:.2em}
form.enq p.sub{color:var(--muted);font-size:.95rem;margin-bottom:18px}
.field{margin-bottom:14px}
.field label{display:block;font-weight:600;font-size:.9rem;margin-bottom:5px;color:var(--slate)}
.field input,.field select,.field textarea{width:100%;padding:12px 14px;border:1px solid #c7d3dd;border-radius:8px;font-family:var(--body);font-size:1rem;color:var(--ink);background:#fff}
.field textarea{min-height:96px;resize:vertical}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--blue);outline:2px solid rgba(25,146,202,.25);outline-offset:0}
.form-row{display:grid;grid-template-columns:1fr 1fr;gap:14px}
form.enq button{width:100%;margin-top:6px}
.form-note{font-size:.82rem;color:var(--muted);margin:12px 0 0;text-align:center}

/* coverage / suburbs */
.subs{display:flex;flex-wrap:wrap;gap:11px;margin-top:26px}
.subs a{display:inline-flex;align-items:center;gap:8px;background:#fff;border:1px solid var(--line);border-radius:999px;
  padding:9px 16px;font-weight:600;font-size:.94rem;color:var(--slate);transition:.15s}
.subs a:hover{background:var(--slate);color:#fff;border-color:var(--slate);text-decoration:none}
.subs a i{color:var(--blue);font-size:.8rem}
.subs a:hover i{color:#fff}

/* faq */
.faq details{background:#fff;border:1px solid var(--line);border-radius:10px;margin-bottom:12px;overflow:hidden}
.faq summary{cursor:pointer;list-style:none;padding:18px 22px;font-family:var(--head);font-weight:700;color:var(--slate);font-size:1.06rem;display:flex;justify-content:space-between;align-items:center;gap:14px}
.faq summary::-webkit-details-marker{display:none}
.faq summary i{color:var(--blue-dark);transition:.2s;flex:none}
.faq details[open] summary i{transform:rotate(45deg)}
.faq .a{padding:0 22px 20px;color:var(--muted)}
.faq .a p{margin:0}

/* final cta */
.final{background:linear-gradient(135deg,var(--red) 0%,var(--red-dark) 100%);color:#fff;text-align:center}
.final h2{color:#fff}
.final p{color:#ffe3e4;max-width:60ch;margin:0 auto 26px;font-size:1.12rem}
.final .hero-cta{justify-content:center}

/* footer */
footer.site{background:var(--navy);color:#c6d3df;font-size:.95rem}
footer.site .cols{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:36px;padding:56px 0 40px}
footer.site h4{color:#fff;font-size:1.02rem;margin-bottom:16px;text-transform:uppercase;letter-spacing:.5px}
footer.site a{color:#c6d3df}
footer.site a:hover{color:#fff}
footer.site ul{list-style:none;padding:0;margin:0}
footer.site li{margin-bottom:10px}
footer .fbrand img{height:64px;margin-bottom:16px;background:#fff;padding:8px;border-radius:8px}
footer .fbrand p{font-size:.95rem;line-height:1.7}
footer .contact-li{display:flex;gap:10px;align-items:flex-start}
footer .contact-li i{color:var(--blue);margin-top:4px;width:18px;text-align:center}
.fbar{border-top:1px solid rgba(255,255,255,.12);padding:18px 0;font-size:.86rem}
.fbar .wrap{display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap}

/* sticky mobile call */
.sticky-call{position:fixed;left:0;right:0;bottom:0;z-index:120;display:none;background:var(--red);box-shadow:0 -4px 18px rgba(0,0,0,.2)}
.sticky-call a{display:flex;align-items:center;justify-content:center;gap:10px;color:#fff;font-family:var(--head);font-weight:800;padding:15px;font-size:1.08rem}
.sticky-call a:hover{text-decoration:none}

@media(max-width:960px){
  .grid{grid-template-columns:repeat(2,1fr)}
  .steps{grid-template-columns:repeat(2,1fr)}
  .two,.book .wrap{grid-template-columns:1fr;gap:28px}
  footer.site .cols{grid-template-columns:1fr 1fr}
}
@media(max-width:760px){
  nav.main{position:fixed;inset:0 0 0 auto;width:min(84vw,340px);background:#fff;flex-direction:column;align-items:flex-start;
    padding:80px 26px 26px;transform:translateX(105%);transition:.25s;box-shadow:-10px 0 30px rgba(0,0,0,.15);overflow-y:auto}
  nav.main.open{transform:translateX(0)}
  nav.main ul{flex-direction:column;align-items:flex-start;gap:6px;width:100%}
  .has-drop{width:100%}
  .drop{position:static;transform:none;display:flex;box-shadow:none;border:0;padding:4px 0 4px 14px;min-width:0}
  .has-drop:hover .drop{display:flex}
  .burger{display:block;z-index:130}
  .hactions .btn-blue span.num{display:none}
  .feat{grid-template-columns:1fr}
  .trust .wrap{justify-content:flex-start}
  .sticky-call{display:block}
  body{padding-bottom:56px}
  .form-row{grid-template-columns:1fr}
}
